\xi(x) = 
\begin{cases}
		A &\text{if $x$ is not a function whose}\\
		&\hspace{1em}\text{domain is an ordinal; otherwise:}\\
		\tau(x(\alpha)) & \text{if $\dom{x} = \ordsucc{\alpha}$}\\
		\theta(\ran{x}) & \text{if $\dom{x}$ is a limit ordinal}
\end{cases}

